if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_6468441ce1833cebafdd2a531d6dc09b' and md5(to_jsonb(t)::text)='07d69b0e9f4c2d9e9e0d6b1a6b73b188')then raise exception 'ITEM_TEXT_CONFLICT:ece:gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_6468441ce1833cebafdd2a531d6dc09b';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{rules,definition,description}',$text_7b4b61a96e239007$[{"id":"current-description","text":"Objeto narrativo sin bonificación mecánica definida.","type":"paragraph","section":"description","sourceIds":["ece-current-copy"],"provenance":"campaign"},{"id":"recovered-campaign-description","text":"Núcleo Luciente Fragmentado\nUno de los objetos más importantes del grupo.\n\nHistoria\nAños atrás Draven participó en una excavación ilegal financiada por un noble sureño.\nAllí encontró un pequeño núcleo cristalino incrustado en una maquinaria imposible.\nEl mecanismo estaba destruido.\nEl cristal permanecía activo.\nDesde entonces lo estudia obsesivamente.\n\nLo importante\nNi Draven.\nNi Viktor.\nNi Severino.\nComprenden realmente qué es.\nPero Severino sospecha que puede constituir la clave para reproducir ciertos fenómenos observados en artefactos aelorianos.\nPor eso insiste en llevar a Draven en esta expedición.","type":"paragraph","section":"flavor","sourceIds":["ece-campaign-document"],"provenance":"campaign"}]$text_7b4b61a96e239007$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_d18eb8837908ca8b$["current-description","recovered-campaign-description"]$text_d18eb8837908ca8b$::jsonb?id),jsonb_build_array('current-description')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_6468441ce1833cebafdd2a531d6dc09b';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_6a6ac05b61e07639932c9c40b37b1521' and md5(to_jsonb(t)::text)='4ad20bb75939dce4075f1cf06e1559f8')then raise exception 'ITEM_TEXT_CONFLICT:ece:gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_6a6ac05b61e07639932c9c40b37b1521';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_1c6fcc112db180f2$[{"id":"preserved-personal-rule","kind":"other","name":"Reglas de la variante personal","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Bolsa de contención creada mediante Replicar objeto mágico.\n\nEsta bolsa posee un espacio interior considerablemente mayor que sus dimensiones exteriores, que son de 60 cm de diámetro en la abertura y 1,2 m de profundidad. La bolsa puede contener hasta 250 kg, con un volumen máximo de 2 m3. La bolsa pesa 7,5 kg, independientemente de su contenido. Sacar un objeto de la bolsa cuesta una acción.\n\nSi se sobrecarga, perfora o rasga la bolsa, esta se rompe y se destruye, y su contenido se dispersa por el Plano Astral. Si se pone la bolsa del revés, su contenido se vuelca sin sufrir daño, pero la bolsa debe volver a ponerse del derecho antes de usarla de nuevo. Las criaturas que se encuentren en el interior de la bolsa y que necesiten respirar podrán sobrevivir una cantidad de minutos igual a 10 dividida entre el número de criaturas (como mínimo 1 minuto). Después, se ahogarán.\n\nMeter una bolsa de contención en el espacio extradimensional creado por un morral práctico, un agujero portátil o un objeto similar destruye instantáneamente ambos objetos y abre un portal al Plano Astral. El portal se crea en el sitio en el que un objeto se introdujo dentro del otro. El portal absorbe a todas las criaturas que estén a 3 m o menos de él y las conduce a un lugar aleatorio del Plano Astral. Después, el portal se cierra. El portal solo funciona en un sentido y no puede volverse a abrir.","showInActions":false}]$text_1c6fcc112db180f2$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_6a6ac05b61e07639932c9c40b37b1521';
